// Precomputed ngspice reference data (web/public/reference/<example>.json, generated by scripts/gen_reference.py).
// It exists only for the unmodified bundled examples and is NOT a live ngspice run.
import { eng, groupSignals } from "./format";
import type { Extra } from "./plots";
import type { Analysis, RunOk } from "./types";

export interface RefSignal {
  name: string;
  part: "magnitude" | "phase" | null;
  values: (number | null)[];
}
export interface RefAnalysis {
  type: string;
  x: number[];
  signals: RefSignal[];
}
export interface RefFile {
  example: string;
  ngspice: string;
  analyses: RefAnalysis[];
}
export interface Overlay {
  extras: Map<string, Extra[]>; // plot group id -> reference traces to draw dashed
  op: Map<string, number>; // .op reference values by signal name
  summary: string; // "max difference ..." for the small error panel
  rows: { label: string; worst: string }[];
}

export async function loadReference(example: string): Promise<RefFile | null> {
  const response = await fetch(new URL(`reference/${encodeURIComponent(example)}.json`, document.baseURI));
  return response.ok ? ((await response.json()) as RefFile) : null;
}

/** Linear interpolation of (xs, ys) onto `target`; identity when the grids already coincide. */
export function resample(xs: number[], ys: (number | null)[], target: (number | null)[]): (number | null)[] {
  if (xs.length === target.length && xs.every((x, i) => Math.abs(x - (target[i] as number)) <= 1e-9 * Math.max(Math.abs(x), 1e-300))) return ys;
  const out: (number | null)[] = [];
  let j = 0;
  for (const t of target) {
    if (t === null || t < xs[0] || t > xs[xs.length - 1]) {
      out.push(null);
      continue;
    }
    while (j < xs.length - 2 && xs[j + 1] < t) j++;
    const [a, b] = [ys[j], ys[j + 1]];
    if (a === null || b === null) out.push(null);
    else {
      const f = xs[j + 1] === xs[j] ? 0 : (t - xs[j]) / (xs[j + 1] - xs[j]);
      out.push(a + f * (b - a));
    }
  }
  return out;
}

/** Largest |a - b| over the points where both exist, and the peak of |b|. */
export function maxDiff(a: (number | null)[], b: (number | null)[]): { diff: number; peak: number } {
  let diff = 0;
  let peak = 0;
  for (let i = 0; i < a.length; i++) {
    if (a[i] === null || b[i] === null) continue;
    diff = Math.max(diff, Math.abs((a[i] as number) - (b[i] as number)));
    peak = Math.max(peak, Math.abs(b[i] as number));
  }
  return { diff, peak };
}

function sci(v: number): string {
  return v === 0 ? "0" : v.toExponential(1).replace("e+", "e");
}

/** Build the overlay for each analysis of a run of an unmodified bundled example (matched by order and type). */
export function overlayFor(ref: RefFile, res: RunOk): Map<number, Overlay> {
  const out = new Map<number, Overlay>();
  res.analyses.forEach((a, i) => {
    const r = ref.analyses[i];
    if (!r || r.type !== a.type) return;
    out.set(i, compare(a, r));
  });
  return out;
}

function compare(a: Analysis, r: RefAnalysis): Overlay {
  const extras = new Map<string, Extra[]>();
  const op = new Map<string, number>();
  const rows: { label: string; worst: string }[] = [];
  const find = (name: string, part: string | null) => r.signals.find((s) => s.name === name && s.part === part);
  if (a.type === "op") {
    let worst = 0;
    let who = "";
    for (const s of a.signals) {
      const m = find(s.name, null);
      if (!m || m.values[0] === null || s.values[0] === null) continue;
      op.set(s.name, m.values[0]);
      const d = Math.abs(s.values[0] - m.values[0]);
      if (d >= worst) [worst, who] = [d, s.name];
    }
    const unit = a.signals.find((s) => s.name === who)?.unit ?? "";
    return { extras, op, summary: who ? `${eng(worst, unit, 3)} (${who})` : "n/a", rows: who ? [{ label: "operating point", worst: `${eng(worst, unit, 3)} on ${who}` }] : [] };
  }
  const xs = a.x!.values;
  const parts: string[] = [];
  for (const g of groupSignals(a)) {
    const list: Extra[] = [];
    let worst = { diff: -1, peak: 0, name: "" };
    for (const s of g.signals) {
      const m = find(s.name, s.part);
      if (!m) continue;
      const values = resample(r.x, m.values, xs);
      list.push({ label: `ngspice ${s.name}`, values });
      const d = maxDiff(s.values, values);
      if (d.diff > worst.diff) worst = { ...d, name: s.name };
    }
    if (!list.length) continue;
    extras.set(g.id, list);
    const unit = g.phase ? "deg" : g.yLabel === "dB" ? "dB" : g.yLabel === "V" ? "V" : "A";
    const text = unit === "dB" || unit === "deg" ? `${sci(worst.diff)} ${unit}` : `${eng(worst.diff, unit, 3)}, ${sci(worst.peak ? worst.diff / worst.peak : 0)} of peak`;
    rows.push({ label: g.title, worst: `${text} on ${worst.name}` });
    parts.push(`${g.title.toLowerCase()} ${text}`);
  }
  return { extras, op, summary: parts.join("; ") || "n/a", rows };
}